import "../state.js";
import "./placement_validator.js";

/**
 * AvailabilityShading — aSc-style whole-grid availability heatmap on card select/pickup.
 *
 * When a card is in hand (APP.editor.cardInHand), shades every visible slot across the grid
 * using the existing classifier `Placement.classify()`.
 *
 * Three states:
 *   - ok: clean placement (green)
 *   - soft-conflict: breaks a soft preference (amber)
 *   - hard-conflict: hard constraint violation / forbidden (red)
 *
 * Performance:
 *   - Caches `classify()` results per (day, period, room) to finish in < 50ms across >900 slots.
 *   - Cleared on drop, restore, cancel, or Escape.
 */
(function () {
  "use strict";

  let activeInHand = null;
  let cache = new Map();
  let lastDurationMs = 0;
  let scheduledFrame = null;

  function classifySlot(slot, inHand) {
    const hand = inHand || (window.APP && window.APP.editor && window.APP.editor.cardInHand);
    if (!hand || !hand.lessonId) return { validity: "green", state: "ok", reasons: [] };

    const d = parseInt(slot.dataset.day, 10);
    const p = parseInt(slot.dataset.period, 10);
    if (Number.isNaN(d) || Number.isNaN(p)) {
      return { validity: "green", state: "ok", reasons: [] };
    }

    const S = window.APP && window.APP.school;
    const lesson = S && S._idx ? S._idx.lessonById[hand.lessonId] : null;
    const perspective = (window.APP && window.APP.editor && window.APP.editor.perspective) || "class";

    let rid;
    if (perspective === "room") {
      rid = slot.dataset.row || slot.closest(".chrx-row")?.dataset.row;
    } else {
      rid = hand.originClassroomId || (lesson ? lesson.preferredRoomId : undefined);
    }

    const cacheKey = d + "_" + p + "_" + (rid || "");
    if (cache.has(cacheKey)) {
      return cache.get(cacheKey);
    }

    let res;
    if (window.Placement && typeof window.Placement.classify === "function") {
      res = window.Placement.classify(hand.lessonId, d, p, rid);
    } else {
      res = { validity: "green", reasons: [] };
    }

    let state = "ok";
    if (res.validity === "amber") {
      state = "soft-conflict";
    } else if (res.validity === "red") {
      state = "hard-conflict";
    }

    const result = {
      validity: res.validity || "green",
      state,
      reasons: res.reasons || []
    };

    cache.set(cacheKey, result);
    return result;
  }

  function paint(inHand) {
    const hand = inHand || (window.APP && window.APP.editor && window.APP.editor.cardInHand);
    if (!hand || !hand.lessonId) return;

    activeInHand = hand;
    cache.clear();

    const t0 = (typeof performance !== "undefined" && typeof performance.now === "function")
      ? performance.now()
      : Date.now();

    const slots = document.querySelectorAll("#editor-root .chrx-slot, .chrx-editor .chrx-slot");
    const counts = { ok: 0, soft: 0, hard: 0 };
    const len = slots.length;

    for (let i = 0; i < len; i++) {
      const slot = slots[i];
      const d = parseInt(slot.dataset.day, 10);
      const p = parseInt(slot.dataset.period, 10);
      if (Number.isNaN(d) || Number.isNaN(p)) continue;

      const res = classifySlot(slot, hand);
      const state = res.state;

      if (state === "ok") {
        slot.classList.add("chrx-avail-ok", "chrx-slot--avail-ok");
        slot.setAttribute("data-availability", "ok");
        counts.ok++;
      } else if (state === "soft-conflict") {
        slot.classList.add("chrx-avail-soft-conflict", "chrx-slot--avail-soft-conflict");
        slot.setAttribute("data-availability", "soft-conflict");
        counts.soft++;
      } else {
        slot.classList.add("chrx-avail-hard-conflict", "chrx-avail-forbidden", "chrx-slot--avail-hard-conflict", "chrx-slot--avail-forbidden");
        slot.setAttribute("data-availability", "hard-conflict");
        counts.hard++;
      }
    }

    const t1 = (typeof performance !== "undefined" && typeof performance.now === "function")
      ? performance.now()
      : Date.now();
    lastDurationMs = t1 - t0;

    renderLegend(counts);

    // If grid re-renders immediately on the same tick (e.g. click mode), schedule a re-apply
    if (scheduledFrame) cancelAnimationFrame(scheduledFrame);
    scheduledFrame = requestAnimationFrame(() => {
      scheduledFrame = null;
      if (activeInHand && window.APP?.editor?.cardInHand) {
        reapplyIfRendered(counts);
      }
    });
  }

  function reapplyIfRendered(counts) {
    if (!activeInHand) return;
    const unshaded = document.querySelector(".chrx-editor .chrx-slot:not([data-availability])");
    if (!unshaded) return;

    const slots = document.querySelectorAll("#editor-root .chrx-slot, .chrx-editor .chrx-slot");
    const len = slots.length;
    for (let i = 0; i < len; i++) {
      const slot = slots[i];
      if (slot.hasAttribute("data-availability")) continue;
      const res = classifySlot(slot, activeInHand);

      const state = res.state;
      if (state === "ok") {
        slot.classList.add("chrx-avail-ok", "chrx-slot--avail-ok");
        slot.setAttribute("data-availability", "ok");
      } else if (state === "soft-conflict") {
        slot.classList.add("chrx-avail-soft-conflict", "chrx-slot--avail-soft-conflict");
        slot.setAttribute("data-availability", "soft-conflict");
      } else {
        slot.classList.add("chrx-avail-hard-conflict", "chrx-avail-forbidden", "chrx-slot--avail-hard-conflict", "chrx-slot--avail-forbidden");
        slot.setAttribute("data-availability", "hard-conflict");
      }
    }
    renderLegend(counts);
  }

  function renderLegend(counts) {
    const host = document.getElementById("editor-inspector-root");
    if (!host) return;

    let legend = document.getElementById("chrx-availability-legend");
    if (!legend) {
      legend = document.createElement("div");
      legend.id = "chrx-availability-legend";
      legend.className = "chrx-availability-legend";
      host.appendChild(legend);
    }

    legend.innerHTML = `
      <div class="chrx-avail-legend-title">Availability</div>
      <div class="chrx-avail-legend-items">
        <span class="chrx-avail-legend-item is-ok">
          <span class="chrx-avail-dot is-ok"></span>
          <span class="chrx-avail-label">Free (${counts.ok || 0})</span>
        </span>
        <span class="chrx-avail-legend-item is-soft">
          <span class="chrx-avail-dot is-soft"></span>
          <span class="chrx-avail-label">Soft conflict (${counts.soft || 0})</span>
        </span>
        <span class="chrx-avail-legend-item is-hard">
          <span class="chrx-avail-dot is-hard"></span>
          <span class="chrx-avail-label">Forbidden (${counts.hard || 0})</span>
        </span>
      </div>
    `;
  }

  function clear() {
    activeInHand = null;
    cache.clear();
    if (scheduledFrame) {
      cancelAnimationFrame(scheduledFrame);
      scheduledFrame = null;
    }

    const shadedSlots = document.querySelectorAll(
      ".chrx-avail-ok, .chrx-avail-soft-conflict, .chrx-avail-hard-conflict, .chrx-avail-forbidden, " +
      ".chrx-slot--avail-ok, .chrx-slot--avail-soft-conflict, .chrx-slot--avail-hard-conflict, .chrx-slot--avail-forbidden, " +
      "[data-availability]"
    );

    for (let i = 0; i < shadedSlots.length; i++) {
      const el = shadedSlots[i];
      el.classList.remove(
        "chrx-avail-ok", "chrx-avail-soft-conflict", "chrx-avail-hard-conflict", "chrx-avail-forbidden",
        "chrx-slot--avail-ok", "chrx-slot--avail-soft-conflict", "chrx-slot--avail-hard-conflict", "chrx-slot--avail-forbidden"
      );
      el.removeAttribute("data-availability");
    }

    const legend = document.getElementById("chrx-availability-legend");
    if (legend && legend.parentNode) {
      legend.parentNode.removeChild(legend);
    }
  }

  // Safety listeners for clean state management
  if (typeof document !== "undefined") {
    document.addEventListener("editor:place", () => clear());
    document.addEventListener("editor:restore", () => clear());
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") clear();
    }, true);
  }

  window.AvailabilityShading = {
    paint,
    clear,
    classifySlot,
    get lastDurationMs() {
      return lastDurationMs;
    }
  };
})();

// [vite-esm] exports auto-generated by the 2026-07 Vite migration.
export const AvailabilityShading = window.AvailabilityShading;
